def solve(grid):
    rows = len(grid)
    cols = len(grid[0])

    # Find row groups (contiguous sets of non-separator rows)
    row_groups = []
    i = 0
    while i < rows:
        if all(grid[i][j] == 5 for j in range(cols)):
            i += 1
        else:
            start = i
            while i < rows and not all(grid[i][j] == 5 for j in range(cols)):
                i += 1
            row_groups.append(list(range(start, i)))

    # Find col groups
    col_groups = []
    j = 0
    while j < cols:
        if all(grid[i][j] == 5 for i in range(rows)):
            j += 1
        else:
            start = j
            while j < cols and not all(grid[i][j] == 5 for i in range(rows)):
                j += 1
            col_groups.append(list(range(start, j)))

    R = len(row_groups)
    C = len(col_groups)

    import copy
    result = copy.deepcopy(grid)

    for k in range(3):
        ri = round(k * (R - 1) / 2)
        ci = round(k * (C - 1) / 2)
        for r in row_groups[ri]:
            for c in col_groups[ci]:
                if result[r][c] == 0:
                    result[r][c] = k + 1

    return result
